// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { Watchlist } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Finance/Watchlist)

figma.connect(Watchlist, FIGMA_NODE_URL, {
  props: {
    dense: figma.boolean('dense'),
  },
  example: ({ dense }) => (
    <Watchlist dense={dense}></Watchlist>
  ),
});
